import json
import numpy as np
from sklearn.metrics import roc_auc_score

def load_signals(path):
    with open(path) as f:
        return json.load(f)

def extract_arrays(data):
    s1 = np.array([d['s1_embedding'] for d in data if d['s1_embedding'] is not None])
    s2 = np.array([d['s2_minkpp'] for d in data if d['s2_minkpp'] is not None])
    s4 = np.array([d['s4_selfcritique'] for d in data if d['s4_selfcritique'] is not None])
    return {'s1_embedding': s1, 's2_minkpp': s2, 's4_selfcritique': s4}

def best_auc(signals, labels):
    if len(np.unique(labels)) < 2:
        return None
    auc_pos = roc_auc_score(labels, signals)
    auc_neg = roc_auc_score(labels, -signals)
    return float(max(auc_pos, auc_neg))

benchmarks = ['mmlu', 'gsm8k', 'arc_challenge']
signal_names = ['s1_embedding', 's2_minkpp', 's4_selfcritique']

# Paths
configs = {
    'd000': {bm: f'/root/autodl-tmp/exp002/signals/Qwen2.5-0.5B_d000_s42/signals_merged_{bm}.json' for bm in benchmarks},
    'd005': {bm: f'/root/autodl-tmp/exp002/signals/Qwen2.5-0.5B_d005_s42/signals_merged_{bm}.json' for bm in benchmarks},
    'd100': {bm: f'/root/autodl-tmp/exp002/signals/Qwen2.5-0.5B_d100_s42/signals_merged_{bm}.json' for bm in benchmarks},
    'rl_aligned': {
        'mmlu': '/root/autodl-tmp/exp008/signals/rl_aligned/mmlu/signals_merged_mmlu.json',
        'gsm8k': '/root/autodl-tmp/exp008/signals/rl_aligned/gsm8k/signals_merged_gsm8k.json',
        'arc_challenge': '/root/autodl-tmp/exp008/signals/rl_aligned/arc_challenge/signals_merged_arc_challenge.json',
    }
}

label_paths = {
    'd005': {bm: f'/root/autodl-tmp/exp001/sft_data_qc_filtered/contamination_labels_{bm}_d005.json' for bm in benchmarks},
    'd100': {bm: f'/root/autodl-tmp/exp001/sft_data_qc_filtered/contamination_labels_{bm}_d100.json' for bm in benchmarks},
}

auc_results = {}

for dose_label, lbl_map in label_paths.items():
    auc_results[f'using_{dose_label}_labels'] = {}
    for bm in benchmarks:
        with open(lbl_map[bm]) as f:
            lbl_data = json.load(f)
        labels = np.array(lbl_data['labels'])
        n_contam = int(np.sum(labels))
        n_total = len(labels)

        print(f"\n{bm.upper()} with {dose_label} labels ({n_contam}/{n_total} contaminated):")

        bm_auc = {'contaminated_count': n_contam, 'total': n_total}

        for regime_name, path_map in configs.items():
            data = load_signals(path_map[bm])
            sigs = extract_arrays(data)

            regime_auc = {}
            for sig in signal_names:
                arr = sigs[sig]
                n = min(len(arr), len(labels))
                auc = best_auc(arr[:n], labels[:n])
                regime_auc[sig] = auc

            bm_auc[regime_name] = regime_auc
            s1a = regime_auc['s1_embedding']
            s2a = regime_auc['s2_minkpp']
            s4a = regime_auc['s4_selfcritique']
            print(f"  {regime_name:12s}: S1={s1a:.4f}, S2={s2a:.4f}, S4={s4a:.4f}")

        auc_results[f'using_{dose_label}_labels'][bm] = bm_auc

# Save
with open('/tmp/regime_auc_results.json', 'w') as f:
    json.dump(auc_results, f, indent=2)

print("\n\nAUC results saved.")
PYEOF
